class ROOT(object):
    """ROOT is a sentinel representing the root target of a glom call.

    While ``T`` refers to the current target (which may change during
    nested processing), ``ROOT`` always refers to the original input
    data passed to :func:`glom`.

    >>> target = {'a': {'b': 1}}
    >>> glom(target, T['a'])
    {'b': 1}
    >>> glom(target, {T['name']: ROOT['a']['b']})
    Traceback (most recent call last):
    ...
    KeyError: 'name'

    This is particularly useful when you need to reference the original
    data while processing nested structures.
    """
    def __repr__(self):
        return 'ROOT'


class Auto(object):
    """Auto objects automatically wrap values in Specs for seamless
    integration into specs.

    When an Auto object is encountered in a spec, it is processed
    recursively, wrapping non-spec values as needed.

    >>> from glom import glom
    >>> target = {'a': {'b': 1}}
    >>> glom(target, Auto({'x': ('a', 'b')}))
    {'x': 1}
    """
    def __init__(self, spec):
        self.spec = spec

    def glomit(self, target, scope):
        return scope[glom](target, self.spec, scope)

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r)' % (cn, self.spec)


class Fill(object):
    """Fill objects specify default values for missing keys or paths.

    Unlike Coalesce which tries multiple subspecs, Fill provides a
    default value when the specified path doesn't exist.

    Args:
       spec: The spec to try first
       default: The default value if spec fails

    >>> target = {'a': 1}
    >>> glom(target, Fill('b', default=0))
    0
    >>> glom(target, Fill('a', default=0))
    1
    """
    def __init__(self, spec, default=None):
        self.spec = spec
        self.default = default

    def glomit(self, target, scope):
        try:
            return scope[glom](target, self.spec, scope)
        except GlomError:
            return self.default

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r, default=%r)' % (cn, self.spec, self.default)


class Invoke(object):
    """Invoke objects call a function/method on the target.

    Similar to Call but designed for method invocation patterns.

    Args:
       name: The attribute name to invoke (as string or T expression)
       *args: Positional arguments to pass
       **kwargs: Keyword arguments to pass

    >>> class Example:
    ...     def greet(self, name):
    ...         return 'Hello, ' + name
    >>> target = Example()
    >>> glom(target, Invoke('greet', 'World'))
    'Hello, World'
    """
    def __init__(self, name, *args, **kwargs):
        self.name = name
        self.args = args
        self.kwargs = kwargs

    def glomit(self, target, scope):
        if isinstance(self.name, TType):
            attr_name = scope[glom](target, self.name, scope)
        else:
            attr_name = self.name
        func = getattr(target, attr_name)
        eval_args = []
        for a in self.args:
            if isinstance(a, (Spec, TType)):
                eval_args.append(scope[glom](target, a, scope))
            else:
                eval_args.append(a)
        eval_kwargs = {}
        for k, v in self.kwargs.items():
            if isinstance(v, (Spec, TType)):
                eval_kwargs[k] = scope[glom](target, v, scope)
            else:
                eval_kwargs[k] = v
        return func(*eval_args, **eval_kwargs)

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r, %s%s)' % (
            cn, self.name,
            ', '.join(repr(a) for a in self.args),
            ', '.join('%s=%r' % (k, v) for k, v in self.kwargs.items()))


class Iter(object):
    """Iter objects iterate over an iterable, applying a subspec to each item.

    Similar to using a list spec, but more explicit about iteration.

    Args:
       subspec: The spec to apply to each item

    >>> target = [1, 2, 3]
    >>> glom(target, Iter(T * 2))
    [2, 4, 6]
    """
    def __init__(self, subspec):
        self.subspec = subspec

    def glomit(self, target, scope):
        ret = []
        iterate = scope[TargetRegistry].get_handler('iterate', target, path=scope[Path])
        try:
            iterator = iterate(target)
        except Exception as e:
            raise TypeError('failed to iterate on instance of type %r at %r (got %r)'
                            % (target.__class__.__name__, Path(*scope[Path]), e))
        for i, t in enumerate(iterator):
            val = scope[glom](t, self.subspec, scope.new_child({Path: scope[Path] + [i]}))
            if val is SKIP:
                continue
            if val is STOP:
                break
            ret.append(val)
        return ret

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r)' % (cn, self.subspec)


class Let(object):
    """Let objects bind variables in scope for later use.

    Allows creating named bindings that can be referenced by S expressions.

    Args:
       name: The variable name (string)
       value: The value to bind (can be a spec)

    >>> target = {'a': 1, 'b': 2}
    >>> glom(target, Let('x', T['a']) + Let('y', T['b']), scope={})
    Traceback (most recent call last):
    ...
    TypeError: unsupported operand type(s) for +: 'int' and 'int'

    Actually, Let returns a dict binding:
    >>> glom({'a': 1}, Let('x', T['a']))
    {'x': 1}
    """
    def __init__(self, name, value):
        self.name = name
        self.value = value

    def glomit(self, target, scope):
        val = scope[glom](target, self.value, scope)
        new_scope = dict(scope)
        new_scope[self.name] = val
        # Return the bound value, updating scope for parent
        scope[self.name] = val
        return val

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r, %r)' % (cn, self.name, self.value)


